draw(surface((4,0,4)--(0,4,4)--(0,0,4)--cycle),gray(0.7),nolight);

draw((0,0,0)--(4,0,0),dashed);
draw((0,0,0)--(0,4,0),dashed);
draw((4,0,0)--(5,0,0));
draw((0,4,0)--(0,5,0));
draw((0,0,0)--(0,0,4),dashed);
draw((0,0,4)--(0,0,5));
draw((4,0,0)--(0,4,0)--(0,4,4)--(4,0,4)--cycle);
draw((4,0,4)--(0,0,4)--(0,4,4));

dot("$(4,0,0)$", (4,0,0), SE);
dot("$(0,4,0)$", (0,4,0), S);
dot("$(4,0,4)$", (4,0,4), NW);
dot("$(0,4,4)$", (0,4,4), NE);
[/asy]

